query.base:
TS metrics-gcp.cloudsql_sqlserver.otel-*
| WHERE gcp.resource_type == "cloudsql_database"
// Resolve per minute first: one logical series can be split across several TSDB
// series, so never use MAX(LAST_OVER_TIME()) for the latest value.
| STATS state_flag = MAX(MAX_OVER_TIME(`cloudsql.googleapis.com/database/instance_state`)),
        up = MAX(MAX_OVER_TIME(`cloudsql.googleapis.com/database/up`)),
        ss = SUM(COUNT_OVER_TIME(`cloudsql.googleapis.com/database/sqlserver/memory/page_life_expectancy`))
    BY `@timestamp` = TBUCKET(1 minute), database_id, attributes.state
// SQL Server engine marker (shared metrics carry no engine label), evaluated over the
// whole 24h rule window so an instance that just stopped (and no longer reports
// page_life_expectancy) stays in scope.
| INLINE STATS ss_total = SUM(ss) BY database_id
// Signal window: only the most recent minutes decide the current state.
// Keep this >= 10-15 minutes to tolerate the 3-5+ minute Cloud Monitoring ingest delay.
| WHERE ss_total > 0 AND `@timestamp` >= NOW() - 15 minutes
// attributes.state is only meaningful on instance_state rows whose value is 1
| EVAL current_state = CASE(state_flag == 1, attributes.state, NULL),
       state_ts = CASE(state_flag == 1, `@timestamp`, NULL),
       up_ts = CASE(up IS NOT NULL, `@timestamp`, NULL)
| STATS state = LAST(current_state, state_ts),
        up = LAST(up, up_ts),
        last_seen = MAX(`@timestamp`)
    BY database_id

breach.segment:
WHERE up IS NOT NULL OR state IS NOT NULL
// Breach: not serving (up = 0) or in a non-RUNNING state.
// MAINTENANCE is Google-scheduled; it only alerts if it outlasts the alert delay.
// To ignore owner-stopped instances or maintenance, append e.g.
// | WHERE COALESCE(state, "") NOT IN ("RUNNABLE", "MAINTENANCE")
| WHERE up == 0 OR (state IS NOT NULL AND state != "RUNNING")
| EVAL reason = CASE(
    state IS NOT NULL AND state != "RUNNING", CONCAT("instance_state=", state),
    "up=0 (not serving while RUNNING)")
| KEEP database_id, state, up, reason, last_seen
| SORT database_id
| LIMIT 100
